    if (activeNav === 'Orders') return [['All orders', adminData.orders.filter(order => order.status !== 'completed').length, Package], ['Paid', adminData.orders.filter(order => order.paymentStatus === 'paid').length, ClipboardCheck], ['Preparing', adminData.orders.filter(order => order.status === 'packaging').length, Clock3], ['Ready', adminData.orders.filter(order => order.status === 'ready').length, Package], ['Log', adminData.orders.filter(order => order.status === 'completed').length, FileImage]];
